<?php
$statusLabels = ['draft' => 'پیش‌نویس', 'ordered' => 'ارسال‌شده', 'partial' => 'دریافت مرحله‌ای', 'received' => 'دریافت کامل', 'cancelled' => 'لغوشده'];
?>
<section class="inv-page" dir="rtl">
    <header class="inv-page-head"><div><span class="inv-eyebrow">جزئیات سفارش تأمین</span><h1><i class="fa-solid fa-file-invoice"></i> <?= inv_e($order['order_no']) ?></h1><p><?= inv_e($order['supplier_name']) ?> · <?= inv_e($statusLabels[$order['status']] ?? $order['status']) ?><?php if (!empty($order['expected_date'])): ?> · موعد <?= inv_date($order['expected_date'] . ' 00:00:00') ?><?php endif; ?></p></div><a class="inv-btn inv-btn-secondary" href="<?= inv_e(inv_url('purchase_order')) ?>"><i class="fa-solid fa-arrow-right"></i> فهرست سفارش‌ها</a></header>
    <?php if (!empty($flash)): ?><div class="inv-alert <?= inv_e($flash['type']) ?>" role="status"><?= inv_e($flash['message']) ?></div><?php endif; ?>
    <section class="inv-card"><div class="inv-card-head"><div><h2>ردیف‌های سفارش</h2><p>مبلغ برآوردی: <?= inv_num(array_sum(array_map(static fn($line) => (float) $line['ordered_quantity'] * (float) $line['unit_cost'], $order['lines']))) ?></p></div></div>
        <?php if (in_array($order['status'], ['ordered', 'partial'], true)): ?><form method="post" action="<?= inv_e(inv_url('purchase_order', 'receive', ['id' => $order['id']])) ?>" data-inv-form><?= $csrfHtml ?><div class="inv-table-wrap"><table class="inv-table"><thead><tr><th>قلم</th><th>سفارش‌شده</th><th>دریافت‌شده</th><th>مانده</th><th>ثبت دریافت جدید</th><th>بهای واحد</th></tr></thead><tbody>
            <?php foreach ($order['lines'] as $line): $remaining = max(0, (float) $line['ordered_quantity'] - (float) $line['received_quantity']); ?><tr><td><strong><?= inv_e($line['item_name']) ?></strong><small><?= inv_e($line['sku']) ?> · <?= inv_e($line['unit']) ?></small></td><td><?= inv_num($line['ordered_quantity']) ?></td><td><?= inv_num($line['received_quantity']) ?></td><td><?= inv_num($remaining) ?></td><td><?php if ($remaining > 0): ?><input class="inv-order-input" type="number" min="0" max="<?= inv_e($remaining) ?>" step="0.0001" name="received[<?= (int) $line['id'] ?>]" aria-label="مقدار دریافت <?= inv_e($line['item_name']) ?>"><?php else: ?>کامل<?php endif; ?></td><td><?= inv_num($line['unit_cost']) ?></td></tr><?php endforeach; ?>
            </tbody></table></div><div class="inv-form-actions"><button class="inv-btn inv-btn-primary" type="submit"><i class="fa-solid fa-truck-ramp-box"></i> ثبت دریافت مرحله‌ای</button></div></form>
        <?php else: ?><div class="inv-table-wrap"><table class="inv-table"><thead><tr><th>قلم</th><th>مقدار سفارش</th><th>دریافت‌شده</th><th>بهای واحد</th><th>جمع</th></tr></thead><tbody><?php foreach ($order['lines'] as $line): ?><tr><td><strong><?= inv_e($line['item_name']) ?></strong><small><?= inv_e($line['sku']) ?> · <?= inv_e($line['unit']) ?></small></td><td><?= inv_num($line['ordered_quantity']) ?></td><td><?= inv_num($line['received_quantity']) ?></td><td><?= inv_num($line['unit_cost']) ?></td><td><?= inv_num((float) $line['ordered_quantity'] * (float) $line['unit_cost']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
        <?php if (!empty($order['notes'])): ?><div class="inv-form-note"><i class="fa-solid fa-note-sticky"></i><span><?= inv_e($order['notes']) ?></span></div><?php endif; ?>
        <?php if (in_array($order['status'], ['draft', 'ordered', 'partial'], true)): ?><div class="inv-form-actions">
            <?php if ($order['status'] === 'draft'): ?><form method="post" action="<?= inv_e(inv_url('purchase_order', 'submit', ['id' => $order['id']])) ?>" data-inv-confirm="سفارش ارسال شود؟ مقدار آن به سفارش در راه اقلام افزوده خواهد شد."><?= $csrfHtml ?><button class="inv-btn inv-btn-primary" type="submit"><i class="fa-solid fa-paper-plane"></i> ارسال سفارش</button></form><?php endif; ?>
            <form method="post" action="<?= inv_e(inv_url('purchase_order', 'cancel', ['id' => $order['id']])) ?>" data-inv-confirm="سفارش لغو شود؟ مانده دریافت‌نشده از سفارش در راه کسر می‌شود."><?= $csrfHtml ?><button class="inv-btn inv-btn-ghost" type="submit">لغو سفارش</button></form>
        </div><?php endif; ?>
    </section>
</section>
